serve(withRequestLog("analyse-item", async (req, log: RequestLogHandle) => {
  if (req.method === "OPTIONS") {
    return browserPreflightResponse(req);
  }

  let adminStreak: SupabaseClient | null = null;
  let streakUserId: string | null = null;

  try {
    let rawBody: Record<string, unknown>;
    try {
      rawBody = (await req.json()) as Record<string, unknown>;
    } catch {
      console.warn("Invalid JSON body");
      return pipelineJsonError(req, E.INVALID_BODY, "Invalid JSON body", 400);
    }

    const body = pickBody(rawBody, ANALYSE_ITEM_BODY_KEYS);

    if (body.images !== undefined && !Array.isArray(body.images)) {
      return jsonResponse(req, { error: "images must be an array" }, 400);
    }
    if (body.user_id !== undefined && typeof body.user_id !== "string") {
      return jsonResponse(req, { error: "user_id must be a string" }, 400);
    }
    if (body.mode !== undefined && typeof body.mode !== "string") {
      return jsonResponse(req, { error: "mode must be a string" }, 400);
    }
    if (body.buy_price !== undefined && body.buy_price !== null) {
      const bp = body.buy_price;
      if (typeof bp !== "number" && typeof bp !== "string") {
        return jsonResponse(req, { error: "buy_price must be a number" }, 400);
      }
    }
    if (body.stream !== undefined && typeof body.stream !== "boolean" && typeof body.stream !== "string") {
      return jsonResponse(req, { error: "stream must be a boolean" }, 400);
    }
    const partnerRaw = body.partner_shop_id ?? body.partnerShopId;
    if (
      partnerRaw !== undefined && partnerRaw !== null && String(partnerRaw).trim() !== "" &&
      typeof partnerRaw !== "string"
    ) {
      return jsonResponse(req, { error: "partner_shop_id must be a string UUID" }, 400);
    }

    const validatedImages: ValidatedScanImage[] = [];
    const rawImages = body.images;
    if (Array.isArray(rawImages) && rawImages.length > 0) {
      const capped = rawImages.slice(0, 3);
      for (let i = 0; i < capped.length; i++) {
        const item = capped[i];
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return jsonResponse(req, { error: `images[${i}] must be an object` }, 400);
        }
        const rec = item as Record<string, unknown>;
        const b64 = rec.base64 ?? rec.image_base64;
        const mime = rec.mime ?? rec.mimeType ?? rec.image_type;
        if (typeof b64 !== "string" || !b64.trim()) {
          return jsonResponse(req, { error: `images[${i}] missing base64` }, 400);
        }
        const validatedOne = validateScanImageInput(req, b64, typeof mime === "string" ? mime : undefined);
        if (validatedOne instanceof Response) return imageValidationFailure(req, validatedOne);
        validatedImages.push(validatedOne);
      }
    }

    if (validatedImages.length === 0) {
      const imageRaw = body.imageBase64 ?? body.image_base64;
      if (typeof imageRaw !== "string" || !imageRaw.trim()) {
        return pipelineJsonError(req, E.NO_IMAGE, "No image provided", 400, {
          image: { status: "failed", code: E.NO_IMAGE },
        });
      }
      const mimeField = body.mimeType ?? body.image_type;
      if (mimeField !== undefined && typeof mimeField !== "string") {
        return jsonResponse(req, { error: "mimeType must be a string" }, 400);
      }
      const validatedOne = validateScanImageInput(req, imageRaw, mimeField as string | undefined);
      if (validatedOne instanceof Response) return imageValidationFailure(req, validatedOne);
      validatedImages.push(validatedOne);
    }

    const primaryB64 = validatedImages[0]!.cleanBase64;

    const supabaseUrlEarly = Deno.env.get("SUPABASE_URL") ?? "";
    const supabaseAnonEarly = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
    const networkUserId = await getUserIdFromJwt(supabaseUrlEarly, supabaseAnonEarly, req);
    const serviceKeyForRate = (
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ??
      Deno.env.get("SB_KEY") ??
      ""
    ).trim();
    const serviceRolePresent = Boolean(serviceKeyForRate);
    // Always resolve JWT `sub` when getUser() flakes (common with service role + edge runtime).
    // Never gate this on serviceRolePresent — that path dropped decodeJwtSub and left insertUserId null.
    const jwtUserId = networkUserId ?? decodeJwtSub(req);
    const bodyUserId =
      typeof body.user_id === "string" && body.user_id.trim() ? body.user_id.trim() : undefined;
    if (jwtUserId && bodyUserId && jwtUserId !== bodyUserId) {
      console.warn("body.user_id ignored — does not match JWT subject", { jwtUserId });
    }

    const authHeaderEarly = (req.headers.get("Authorization") ?? req.headers.get("authorization") ?? "").trim();
    console.log("Auth for scans persist:", {
      jwtUserId: jwtUserId ? jwtUserId.slice(0, 8) : null,
      bodyUserId: bodyUserId ? bodyUserId.slice(0, 8) : null,
      hasBearer: authHeaderEarly.startsWith("Bearer "),
      serviceRolePresent,
    });

    const rateLimitUserId = jwtUserId;
    if (serviceKeyForRate && supabaseUrlEarly && rateLimitUserId) {
      const adminRate = createClient(supabaseUrlEarly, serviceKeyForRate, {
        auth: { autoRefreshToken: false, persistSession: false },
      });
      const rateResp = await enforceUserRateLimit({
        admin: adminRate,
        userId: rateLimitUserId,
        functionSlug: RATE_LIMIT_SLUG_ANALYSE_ITEM,
        req,
      });
      if (rateResp) {
        if (rateResp.status === 429) {
          return pipelineJsonError(req, E.RATE_LIMIT, "Rate limit exceeded", 429, {
            rate_limit: { status: "failed", code: E.RATE_LIMIT },
          });
        }
        if (rateResp.status === 503) {
          return pipelineJsonError(req, E.RATE_LIMIT_CHECK, "Rate limit check failed", 503, {
            rate_limit: { status: "failed", code: E.RATE_LIMIT_CHECK },
          });
        }
        return rateResp;
      }
    } else if (!serviceKeyForRate && rateLimitUserId) {
      console.warn(
        "[rateLimit] service role key missing — skipping RPM enforcement for analyse-item (set secret in production).",
      );
    }

    if (serviceKeyForRate && supabaseUrlEarly) {
      adminStreak = createClient(supabaseUrlEarly, serviceKeyForRate, {
        auth: { autoRefreshToken: false, persistSession: false },
      });
    }
    streakUserId = rateLimitUserId ?? jwtUserId ?? null;
    log.setUser(streakUserId);

    const scanId = crypto.randomUUID();
    const streamRaw = body.stream;
    const streamWanted =
      streamRaw === true || (typeof streamRaw === "string" && streamRaw.toLowerCase() === "true");

    let scanFingerprint: string | null = null;
    try {
      scanFingerprint = await fingerprintFromMultipleScanBase64(
        validatedImages.map((v) => v.cleanBase64),
      );
    } catch (e) {
      console.warn(
        "fingerprintFromMultipleScanBase64 failed, identification cache disabled:",
        e instanceof Error ? e.message : "unknown",
      );
    }

    const serviceKeyForCache = (
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ??
      Deno.env.get("SB_KEY") ??
      ""
    ).trim();
    const supabaseUrlForCache = Deno.env.get("SUPABASE_URL") ?? "";
    const supabaseCache =
      scanFingerprint && serviceKeyForCache && supabaseUrlForCache
        ? createClient(supabaseUrlForCache, serviceKeyForCache)
        : null;

    let identificationFromCache = false;
    let cachedIdentification: Record<string, unknown> | null = null;
    if (supabaseCache && scanFingerprint) {
      cachedIdentification = await tryLoadIdentificationCache(supabaseCache, scanFingerprint);
      identificationFromCache = cachedIdentification !== null;
    }

    console.log(
      "Vision path — model:",
      VISION_MODEL,
      "stream:",
      streamWanted,
      "identification_from_cache:",
      identificationFromCache,
    );

    let imageUrl = "";
    let aiResult: Record<string, unknown> = {};

    if (identificationFromCache && cachedIdentification) {
      imageUrl = await uploadToImgbb(primaryB64);
      aiResult = { ...cachedIdentification };
      console.log("Skipped Anthropic vision — using scan_identification_cache");
    } else {
      const [imgUrl, anthropicRes] = await Promise.all([
        uploadToImgbb(primaryB64),
        fetchClaudeVisionBatch(validatedImages),
      ]);
      imageUrl = imgUrl;

      console.log("Anthropic response status:", anthropicRes.status);

      if (!anthropicRes.ok) {
        const errText = await anthropicRes.text();
        console.error("Anthropic error:", anthropicRes.status, "body_len", errText.length);
        await recordScanFailureStreak(adminStreak, streakUserId);
        return pipelineJsonError(req, E.ANTHROPIC, "AI analysis failed", 500, {
          vision: { status: "failed", code: E.ANTHROPIC, detail: String(anthropicRes.status) },
        });
      }

      const anthropicData = await anthropicRes.json();
      const rawText = anthropicData?.content?.[0]?.text ?? "";

      try {
        aiResult = parseAiJsonObject(rawText);
      } catch (e) {
        console.error("Failed to parse AI JSON:", e instanceof Error ? e.message : "parse error");
        await recordScanFailureStreak(adminStreak, streakUserId);
        return pipelineJsonError(req, E.AI_PARSE, "Failed to parse AI response", 500, {
          vision: { status: "failed", code: E.AI_PARSE },
        });
      }
    }

    const brandName: string = resolveBrandName(aiResult);
    console.log("Resolved brand_name:", brandName);
    aiResult = { ...aiResult, brand_name: brandName };

    if (supabaseCache && scanFingerprint) {
      await upsertIdentificationCache(supabaseCache, scanFingerprint, aiResult);
    }

    const searchQuery = buildSearchQuery(aiResult);

    const finishArgs: FinishScanArgs = {
      req,
      body,
      jwtUserId,
      bodyUserId,
      aiResult,
      brandName,
      searchQuery,
      scanId,
      imageUrl,
      fingerprint: scanFingerprint,
      identificationFromCache,
    };

    const cors = corsHeadersForRequest(req);

    if (streamWanted) {
      const streamHeaders = {
        ...cors,
        "Content-Type": "application/x-ndjson",
      };
      const enc = new TextEncoder();
      const stream = new ReadableStream({
        async start(controller) {
          const push = (obj: unknown) => {
            controller.enqueue(enc.encode(`${JSON.stringify(obj)}\n`));
          };
          try {
            push({
              event: "analysis",
              data: {
                ai: aiResult,
                imageUrl,
                searchQuery,
                scanId,
                fingerprint: scanFingerprint,
                identification_from_cache: identificationFromCache,
              },
            });
            const full = await finishScanAfterVision(finishArgs);
            push({
              event: "complete",
              data: { ...full, identification_from_cache: identificationFromCache },
            });
          } catch (e) {
            if (e instanceof Response) {
              console.error("stream scan error: HTTP", e.status);
              let safeMessage = `Request failed (${e.status})`;
              let errorCode = e.status >= 500 ? E.INTERNAL : E.VALIDATION;
              let pipeline_report = buildFailedReport(errorCode);
              try {
                const parsed = JSON.parse(await e.text()) as {
                  error?: string;
                  message?: string;
                  error_code?: string;
                  pipeline_report?: typeof pipeline_report;
                };
                safeMessage = parsed.message ?? parsed.error ?? safeMessage;
                if (parsed.error_code) errorCode = parsed.error_code;
                if (parsed.pipeline_report) pipeline_report = parsed.pipeline_report;
              } catch {
                /* ignore */
              }
              push({
                event: "error",
                message: safeMessage,
                status: e.status,
                error_code: errorCode,
                pipeline_report,
              });
              if (e.status >= 500) await recordScanFailureStreak(adminStreak, streakUserId);
            } else {
              console.error("stream scan error:", e instanceof Error ? e.message : "unknown");
              const pipeline_report = buildFailedReport(E.STREAM);
              push({
                event: "error",
                message: pipeline_report.user_message,
                error_code: E.STREAM,
                pipeline_report,
              });
              await recordScanFailureStreak(adminStreak, streakUserId);
            }
          } finally {
            controller.close();
          }
        },
      });
      return new Response(stream, { status: 200, headers: streamHeaders });
    }

    const full = await finishScanAfterVision(finishArgs);
    return new Response(
      JSON.stringify({ ...full, identification_from_cache: identificationFromCache }),
      { status: 200, headers: { ...cors, "Content-Type": "application/json" } },
    );
  } catch (err) {
    if (err instanceof Response) {
      if (err.status >= 500) await recordScanFailureStreak(adminStreak, streakUserId);
      return err;
    }
    console.error("Edge function unhandled error:", err instanceof Error ? err.message : "unknown");
    await recordScanFailureStreak(adminStreak, streakUserId);
    return pipelineJsonError(req, E.INTERNAL, "Internal server error", 500);
  }
}));

/**
 * Scan image fingerprint + identification payload shape for `scan_identification_cache`.
 * Pricing / comps are never cached here — only vision-equivalent structured fields.
 */

export const IDENT_CACHE_SCHEMA_VERSION = 1;
export const IDENT_CACHE_TTL_MS = 48 * 60 * 60 * 1000;

/** Keys aligned with Anthropic vision JSON (stored in `payload` jsonb). */
export const IDENTIFICATION_PAYLOAD_KEYS = [
  "brand_name",
  "sub_brand",
  "brand_confidence",
  "condition_grade",
  "item_type_bucket",
  "trend_score",
  "colour",
  "gender",
  "item_type",
  "style",
  "category",
  "era",
  "size_label",
] as const;

export type IdentificationPayloadKey = (typeof IDENTIFICATION_PAYLOAD_KEYS)[number];

/** SHA-256 hex of UTF-8 bytes of the base64 image string (after stripping data-URL prefix). Matches Edge + client if both use the same string. */
export async function fingerprintFromScanBase64(cleanBase64: string): Promise<string> {
  const enc = new TextEncoder().encode(cleanBase64);
  const hash = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** One image: same as single-image SHA-256. Multiple: SHA-256 of concatenated per-image SHA-256 hex digests (order preserved). */
export async function fingerprintFromMultipleScanBase64(cleanBase64s: string[]): Promise<string> {
  if (cleanBase64s.length === 0) {
    throw new Error("fingerprintFromMultipleScanBase64: no images");
  }
  if (cleanBase64s.length === 1) return await fingerprintFromScanBase64(cleanBase64s[0]!);
  const parts: string[] = [];
  for (const b64 of cleanBase64s) {
    parts.push(await fingerprintFromScanBase64(b64));
  }
  const fused = parts.join("");
  const enc = new TextEncoder().encode(fused);
  const hash = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export function pickIdentificationPayload(ai: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const k of IDENTIFICATION_PAYLOAD_KEYS) {
    if (k in ai && ai[k] !== undefined) out[k] = ai[k];
  }
  return out;
}

/** True if cached payload has enough signal to skip vision (at least one non-empty identification field). */
export function isIdentificationPayloadUsable(payload: Record<string, unknown>): boolean {
  for (const k of IDENTIFICATION_PAYLOAD_KEYS) {
    const v = payload[k];
    if (v === undefined || v === null) continue;
    if (typeof v === "string" && v.trim() === "") continue;
    if (typeof v === "number" && !Number.isFinite(v)) continue;
    return true;
  }
  return false;
}

export function mergeIdentificationFromCache(
  payload: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const k of IDENTIFICATION_PAYLOAD_KEYS) {
    if (k in payload) out[k] = payload[k];
  }
  return out;
}

/**
 * Browser CORS for SPA → Edge calls. Echo Access-Control-Allow-Origin only for allowlisted origins.
 * Do not use for Stripe webhooks (server-to-server; omit these headers there).
 *
 * Optional: set Edge secret `EDGE_EXTRA_ALLOWED_ORIGINS` to a comma-separated list
 * (e.g. your Readdy preview URL) so the SPA can call functions from that host.
 */

export const BROWSER_ALLOWED_ORIGINS = [
  "https://marginn.co.uk",
  "https://www.marginn.co.uk",
  "http://localhost:5173",
] as const;

export type BrowserAllowedOrigin = (typeof BROWSER_ALLOWED_ORIGINS)[number];

function buildAllowedOriginSet(): Set<string> {
  const set = new Set<string>(BROWSER_ALLOWED_ORIGINS);
  const extra = (typeof Deno !== "undefined" ? Deno.env.get("EDGE_EXTRA_ALLOWED_ORIGINS") : undefined) ??
    "";
  for (const part of extra.split(",")) {
    const o = part.trim();
    if (o) set.add(o);
  }
  return set;
}

const ALLOWED_SET = buildAllowedOriginSet();

export function resolveAllowedBrowserOrigin(originHeader: string | null | undefined): string | null {
  const o = originHeader?.trim() ?? "";
  if (!o) return null;
  return ALLOWED_SET.has(o) ? o : null;
}

const BASE_CORS: Record<string, string> = {
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

/** CORS headers for a browser request; omits ACAO when Origin is missing or not allowlisted. */
export function corsHeadersForRequest(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin") ?? req.headers.get("origin");
  const allowed = resolveAllowedBrowserOrigin(origin);
  if (!allowed) {
    return { ...BASE_CORS };
  }
  return {
    ...BASE_CORS,
    "Access-Control-Allow-Origin": allowed,
    Vary: "Origin",
  };
}

export function browserPreflightResponse(req: Request): Response {
  return new Response(null, {
    status: 204,
    headers: corsHeadersForRequest(req),
  });
}

export function jsonResponse(
  req: Request,
  body: unknown,
  status: number,
  extraHeaders?: HeadersInit,
): Response {
  const headers = new Headers({ "Content-Type": "application/json", ...corsHeadersForRequest(req) });
  if (extraHeaders) {
    new Headers(extraHeaders).forEach((v, k) => headers.set(k, v));
  }
  return new Response(JSON.stringify(body), { status, headers });
}

/** Whitelist keys from a parsed JSON object; unknown fields are dropped. */

export function pickBody<T extends string>(
  body: Record<string, unknown>,
  keys: readonly T[],
): Record<T, unknown> {
  const out = {} as Record<T, unknown>;
  for (const k of keys) {
    if (Object.prototype.hasOwnProperty.call(body, k)) {
      out[k] = body[k];
    }
  }
  return out;
}

import { jsonResponse } from "./cors.ts";

export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

export const ALLOWED_IMAGE_MIMES = ["image/jpeg", "image/png", "image/webp"] as const;
export type AllowedImageMime = (typeof ALLOWED_IMAGE_MIMES)[number];

const MIME_SET = new Set<string>(ALLOWED_IMAGE_MIMES);

export interface ValidatedScanImage {
  cleanBase64: string;
  mimeType: AllowedImageMime;
  decodedByteLength: number;
}

/** Conservative upper bound on decoded bytes from base64 length (ignores whitespace). */
export function impliedDecodedBytesUpperBound(base64NoWs: string): number {
  const n = base64NoWs.length;
  if (n === 0) return 0;
  const padding = base64NoWs.endsWith("==") ? 2 : base64NoWs.endsWith("=") ? 1 : 0;
  return Math.floor((n * 3) / 4) - padding;
}

/**
 * From raw `imageBase64` / `image_base64` field: strip `data:*;base64,` if present.
 * Uses index-based parsing so very large payloads are not scanned by a global regex.
 */
export function splitDataUrlBase64(raw: string): { payload: string; dataUrlMime: string | null } {
  const trimmed = raw.trim();
  if (trimmed.toLowerCase().startsWith("data:")) {
    const sep = trimmed.indexOf(";base64,");
    if (sep !== -1) {
      const mimePart = trimmed.slice(5, sep).trim().toLowerCase();
      const payload = trimmed.slice(sep + ";base64,".length);
      return { payload, dataUrlMime: mimePart || null };
    }
  }
  return { payload: trimmed, dataUrlMime: null };
}

function normalizeMime(m: string | undefined | null): string | null {
  if (m === undefined || m === null) return null;
  const t = String(m).trim().toLowerCase();
  if (t === "image/jpg") return "image/jpeg";
  return t || null;
}

function resolveMime(dataUrlMime: string | null, bodyMime: string | undefined | null): string | null {
  return normalizeMime(dataUrlMime ?? bodyMime) ?? normalizeMime(bodyMime ?? undefined);
}

function isValidBase64Chars(s: string): boolean {
  const noWs = s.replace(/\s/g, "");
  if (noWs.length === 0) return false;
  return /^[A-Za-z0-9+/]+=*$/.test(noWs);
}

/**
 * Validates size (≤ 5MB decoded), MIME (jpeg/png/webp), and base64 shape.
 * Returns a Response on failure (caller should return it).
 */
export function validateScanImageInput(
  req: Request,
  imageField: string,
  bodyMime: string | undefined | null,
): ValidatedScanImage | Response {
  const { payload, dataUrlMime } = splitDataUrlBase64(imageField);
  const cleanBase64 = payload.replace(/\s/g, "");
  const implied = impliedDecodedBytesUpperBound(cleanBase64);
  if (implied > MAX_IMAGE_BYTES) {
    return jsonResponse(
      req,
      {
        error: "Image too large",
        message: `Decoded image would exceed ${MAX_IMAGE_BYTES} bytes (limit is 5MB).`,
      },
      413,
    );
  }

  if (!isValidBase64Chars(cleanBase64)) {
    return jsonResponse(req, { error: "Invalid image data", message: "Payload is not valid base64." }, 400);
  }

  let decoded: Uint8Array;
  try {
    const bin = atob(cleanBase64);
    decoded = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) decoded[i] = bin.charCodeAt(i);
  } catch {
    return jsonResponse(req, { error: "Invalid image data", message: "Base64 decode failed." }, 400);
  }

  if (decoded.byteLength > MAX_IMAGE_BYTES) {
    return jsonResponse(
      req,
      {
        error: "Image too large",
        message: `Decoded image is ${decoded.byteLength} bytes; maximum is ${MAX_IMAGE_BYTES} bytes (5MB).`,
      },
      413,
    );
  }

  const mime = resolveMime(dataUrlMime, bodyMime);
  if (!mime || !MIME_SET.has(mime)) {
    return jsonResponse(
      req,
      {
        error: "Unsupported image type",
        message: "Only image/jpeg, image/png, and image/webp are allowed.",
      },
      400,
    );
  }

  return {
    cleanBase64,
    mimeType: mime as AllowedImageMime,
    decodedByteLength: decoded.byteLength,
  };
}

/**
 * Plan-based rolling 1-minute RPM for Edge functions (see migration `rate_limit_consume` RPC).
 * Requires SUPABASE_SERVICE_ROLE_KEY: RPC is executable by service_role only.
 */
import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsHeadersForRequest } from "./cors.ts";

export const RATE_LIMIT_SLUG_ANALYSE_ITEM = "analyse-item";
export const RATE_LIMIT_SLUG_DELETE_ACCOUNT = "delete-account";

/** Requests per rolling 1-minute window; `pro` matches trader. Unknown plans → free. */
export function rpmForPlan(plan: string | null | undefined): number {
  const p = String(plan ?? "free").trim().toLowerCase();
  switch (p) {
    case "free":
      return 3;
    case "scout":
      return 10;
    case "trader":
    case "pro":
      return 60;
    case "drop_in":
    case "drop-in":
      return 5;
    default:
      return 3;
  }
}

export interface RateLimitRpcResult {
  allowed?: boolean;
  retry_after_sec?: number;
  error?: string;
}

/**
 * Resolves `profiles.plan` (default free), then atomically consumes one slot via RPC.
 * @returns `Response` (429 or 503) when blocked / misconfigured; `null` when the request may proceed.
 */
export async function enforceUserRateLimit(opts: {
  admin: SupabaseClient;
  userId: string;
  functionSlug: string;
  req: Request;
}): Promise<Response | null> {
  const { admin, userId, functionSlug, req } = opts;
  const corsHeaders = corsHeadersForRequest(req);

  const { data: prof, error: profErr } = await admin
    .from("profiles")
    .select("plan")
    .eq("id", userId)
    .maybeSingle();

  if (profErr) {
    console.warn("[rateLimit] profiles lookup:", profErr.message);
  }

  const plan = typeof prof?.plan === "string" ? prof.plan : null;
  const limit = rpmForPlan(plan);

  const { data, error } = await admin.rpc("rate_limit_consume", {
    p_user_id: userId,
    p_function_slug: functionSlug,
    p_limit: limit,
  });

  if (error) {
    console.error("[rateLimit] rate_limit_consume RPC:", error.message);
    return new Response(
      JSON.stringify({ error: "Rate limit check failed", detail: error.message }),
      {
        status: 503,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }

  const row = data as RateLimitRpcResult | null;
  if (row?.allowed === true) return null;

  const sec = Math.max(1, Math.ceil(Number(row?.retry_after_sec ?? 60)));
  const message = `Rate limit exceeded. Try again in ${sec} seconds.`;
  return new Response(JSON.stringify({ message }), {
    status: 429,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json",
      "Retry-After": String(sec),
    },
  });
}

/**
 * One-line structured request logs for Edge functions.
 * Never logs bodies, headers, API keys, or raw JWTs — only a salted short user hash when `uid` is supplied.
 */

export type RequestLogOutcome = "ok" | "error" | "429" | "400";

const te = new TextEncoder();

async function sha256Hex(input: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", te.encode(input));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/** Salted, truncated hash of user id for correlating logs without storing raw ids. */
export async function hashUserIdForLog(userId: string): Promise<string> {
  const salt = (Deno.env.get("REQUEST_LOG_USER_SALT") ?? "").trim();
  const material = salt.length > 0 ? `${userId}:${salt}` : `${userId}:REQUEST_LOG_USER_SALT_UNSET`;
  const hex = await sha256Hex(material);
  return hex.slice(0, 16);
}

export class RequestLogHandle {
  readonly reqId: string;
  readonly fn: string;
  readonly started: number;
  userId: string | null = null;
  /** Short non-sensitive diagnostic (no tokens / PII). */
  detail: string | undefined;

  constructor(fn: string) {
    this.reqId = crypto.randomUUID();
    this.fn = fn;
    this.started = Date.now();
  }

  setUser(id: string | null | undefined) {
    if (id && typeof id === "string") this.userId = id;
  }

  setDetail(msg: string, maxLen = 80) {
    const t = msg.replace(/\s+/g, " ").trim();
    this.detail = t.length > maxLen ? `${t.slice(0, maxLen)}…` : t;
  }
}

function outcomeFromStatus(status: number): RequestLogOutcome {
  if (status === 429) return "429";
  if (status >= 500) return "error";
  if (status >= 400) return "400";
  return "ok";
}

export async function emitRequestLogLine(
  req: Request,
  log: RequestLogHandle,
  res: Response,
): Promise<void> {
  const ms = Date.now() - log.started;
  const st = res.status;
  const outcome = outcomeFromStatus(st);
  const user_h = log.userId ? await hashUserIdForLog(log.userId) : null;
  console.log(
    JSON.stringify({
      req_id: log.reqId,
      fn: log.fn,
      method: req.method,
      outcome,
      http_status: st,
      user_h,
      ts: new Date().toISOString(),
      ms,
      ...(log.detail ? { detail: log.detail } : {}),
    }),
  );
}

/**
 * Wraps a handler so every response emits a single JSON console line (try/finally semantics).
 */
export function withRequestLog(
  fn: string,
  handler: (req: Request, log: RequestLogHandle) => Promise<Response>,
): (req: Request) => Promise<Response> {
  return async (req) => {
    const log = new RequestLogHandle(fn);
    let res: Response;
    try {
      res = await handler(req, log);
    } catch (e) {
      if (e instanceof Response) {
        res = e;
      } else {
        const msg = e instanceof Error ? e.message : String(e);
        log.setDetail(msg);
        res = new Response(JSON.stringify({ error: "Internal server error" }), {
          status: 500,
          headers: { "Content-Type": "application/json" },
        });
      }
    }
    await emitRequestLogLine(req, log, res);
    return res;
  };
}

/**
 * Tracks repeated analyse-item failures per user (Edge + service role RPC).
 * Optional HTTP alert when streak crosses threshold (secrets via env only).
 */
import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

function intEnv(name: string, fallback: number): number {
  const v = Number(Deno.env.get(name) ?? "");
  if (!Number.isFinite(v) || v < 1) return fallback;
  return Math.floor(v);
}

/** Record a server-side scan pipeline failure (5xx-class). No-op if admin client unavailable. */
export async function recordScanFailureStreak(
  admin: SupabaseClient,
  userId: string | null | undefined,
): Promise<void> {
  const uid = typeof userId === "string" && userId.length > 0 ? userId : null;
  if (!uid) return;

  const windowMin = intEnv("SCAN_FAILURE_WINDOW_MINUTES", 15);
  const threshold = intEnv("SCAN_FAILURE_ALERT_THRESHOLD", 5);
  const alertUrl = (Deno.env.get("SCAN_FAILURE_ALERT_URL") ?? "").trim();
  const alertSecret = (Deno.env.get("SCAN_FAILURE_ALERT_SECRET") ?? "").trim();

  const { data, error } = await admin.rpc("scan_failure_streak_record", {
    p_user_id: uid,
    p_window_minutes: windowMin,
  });

  if (error) {
    console.warn("scan_failure_streak_record:", error.message);
    return;
  }

  const row = data as { count?: number } | null;
  const count = typeof row?.count === "number" ? row.count : 0;
  if (count < threshold || !alertUrl) return;

  try {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (alertSecret) headers["X-Webhook-Secret"] = alertSecret;
    await fetch(alertUrl, {
      method: "POST",
      headers,
      body: JSON.stringify({
        event: "scan_failure_streak",
        threshold,
        window_minutes: windowMin,
        failure_count: count,
      }),
    });
  } catch (e) {
    const m = e instanceof Error ? e.message : String(e);
    console.warn("SCAN_FAILURE_ALERT_URL notify failed:", m);
  }
}

/**
 * Data-backed Flip Score (0–10, one decimal) — not Claude `trend_score`.
 *
 * Formula (high level):
 * 1. Sub-scores (each 0–10): velocity, margin, supply_gap, brand_tier, price_stability.
 * 2. weightedBase = Σ (weight_i × sub_i)
 *    weights: velocity 30%, margin 25%, supply_gap 20%, brand_tier 15%, price_stability 10%.
 * 3. afterCondition = weightedBase × conditionModifier (LIKE_NEW 1.00 … HEAVY_WEAR ~0.88).
 * 4. afterSeasonal = afterCondition × seasonalModifier (≈0.97–1.03 from calendar month + item keywords).
 * 5. score = round(clamp(afterSeasonal, 0, 10) × 10) / 10  → one decimal.
 *
 * Sold velocity: prefer `days_ago` on extracted eBay sold cards. If too many nulls, blend in a
 * conservative proxy from SERP sold-marker density (`soldMarkersOnPage`) so d7/d30 are never
 * both zero when the scrape clearly saw activity.
 */

export type FlipScoreConditionGrade =
  | "LIKE_NEW"
  | "GOOD"
  | "LIGHT_WEAR"
  | "FADED"
  | "CRACKED_LOGO"
  | "STAINS"
  | "HEAVY_WEAR";

export interface FlipScoreListingDay {
  days_ago: number | null;
}

export interface CalculateFlipScoreInput {
  /** eBay sold cards for this scrape (same source as listing_cache rows). */
  ebaySoldCards: FlipScoreListingDay[];
  /** Raw £ prices from sold SERP (for IQR / median stability). */
  ebayPrices: number[];
  /** Optional precomputed median / IQR from caller; if omitted, derived from ebayPrices. */
  ebayPriceMedian?: number;
  ebayPriceIqr?: number;
  brandRow: Record<string, unknown> | null;
  condition_grade: string;
  buy_price_gbp: number | null;
  net_profit_gbp: number | null;
  roi_percent: number | null;
  resale_gbp: number;
  /** Total live listing counts (scraped) across platforms — supply proxy. */
  liveListingTotal: number;
  /** Count of sold markers / sold UI hits on full eBay HTML (fallback signal). */
  soldMarkersOnPage: number;
  /** Month 1–12 (UTC) for lightweight seasonality. */
  month?: number;
  /** Vision/AI item keywords: item_type, category, style, brand_name, etc. */
  itemKeywords?: string[];
}

export interface FlipScoreBreakdown {
  velocity: number;
  margin: number;
  supply_gap: number;
  brand_tier: number;
  price_stability: number;
  weights: {
    velocity: number;
    margin: number;
    supply_gap: number;
    brand_tier: number;
    price_stability: number;
  };
  weighted_base: number;
  condition_modifier: number;
  seasonal_modifier: number;
  condition_grade: string;
  sold_velocity: { d7: number; d30: number; method: "days_ago" | "mixed_days_ago_proxy" };
  labels: Record<string, string>;
  /** Claude-only hint; never use as the primary flip score. */
  vision_trend_hint?: number;
}

export interface CalculateFlipScoreResult {
  score: number;
  breakdown: FlipScoreBreakdown;
}

const W_VELOCITY = 0.3;
const W_MARGIN = 0.25;
const W_SUPPLY = 0.2;
const W_BRAND = 0.15;
const W_STAB = 0.1;

const CONDITION_MOD: Record<string, number> = {
  LIKE_NEW: 1.0,
  GOOD: 0.98,
  LIGHT_WEAR: 0.94,
  FADED: 0.9,
  CRACKED_LOGO: 0.9,
  STAINS: 0.88,
  HEAVY_WEAR: 0.86,
};

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

function round1(n: number): number {
  return Math.round(n * 10) / 10;
}

function medianSorted(sorted: number[]): number {
  if (sorted.length === 0) return 0;
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2;
}

function quantileSorted(sorted: number[], q: number): number {
  if (sorted.length === 0) return 0;
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] === undefined) return sorted[base]!;
  return sorted[base]! + rest * (sorted[base + 1]! - sorted[base]!);
}

function iqrFromPrices(prices: number[]): { median: number; iqr: number } {
  if (prices.length === 0) return { median: 0, iqr: 0 };
  const sorted = [...prices].sort((a, b) => a - b);
  const q1 = quantileSorted(sorted, 0.25);
  const q3 = quantileSorted(sorted, 0.75);
  const med = medianSorted(sorted);
  return { median: med, iqr: Math.max(0, q3 - q1) };
}

/**
 * Prefer strict `days_ago` windows. If ≥60% of cards lack `days_ago`, blend in a conservative
 * proxy from `soldMarkersOnPage` so velocity is not falsely zero.
 */
export function resolveSoldVelocity(
  cards: FlipScoreListingDay[],
  soldMarkersOnPage: number,
): { d7: number; d30: number; method: "days_ago" | "mixed_days_ago_proxy" } {
  const n = cards.length;
  if (n === 0) {
    const proxy = Math.min(30, Math.max(0, Math.round(soldMarkersOnPage * 0.35)));
    return {
      d7: Math.round(proxy * (7 / 30) * 0.85),
      d30: proxy,
      method: "mixed_days_ago_proxy",
    };
  }

  const known = cards.filter((c) => c.days_ago !== null && c.days_ago !== undefined && Number.isFinite(c.days_ago));
  const nullHeavy = known.length / n < 0.4;

  let d7 = known.filter((c) => (c.days_ago as number) <= 7).length;
  let d30 = known.filter((c) => (c.days_ago as number) <= 30).length;
  let method: "days_ago" | "mixed_days_ago_proxy" = "days_ago";

  if (nullHeavy) {
    method = "mixed_days_ago_proxy";
    const unknown = n - known.length;
    // Conservative partial credit for undated cards + SERP sold density cap.
    const fromUnknown = Math.round(unknown * 0.22);
    const fromMarkers = Math.round(Math.min(soldMarkersOnPage, 40) * 0.28);
    const floor30 = Math.max(d30, fromUnknown, fromMarkers, d7 > 0 ? d7 * 3 : 0);
    d30 = Math.min(30, Math.max(d30, floor30));
    d7 = Math.max(d7, Math.min(d30, Math.round(d30 * (7 / 30) * 0.85)));
  }

  return { d7, d30, method };
}

function subscoreVelocity(d7: number, d30: number): number {
  // Piecewise demand heat: both windows; cap at 10.
  let s = 2 + Math.min(4, d7 * 0.85) + Math.min(4, Math.log1p(d30) * 1.85);
  if (d30 >= 8) s += 0.8;
  if (d7 >= 3) s += 0.6;
  return round1(clamp(s, 0, 10));
}

function subscoreMargin(
  buy: number | null,
  net: number | null,
  roi: number | null,
  resale: number,
): number {
  if (buy === null || buy <= 0 || net === null) {
    // No buy price: neutral-to-slight optimism from resale level only
    const hint = resale >= 80 ? 5.8 : resale >= 40 ? 5.2 : 4.6;
    return round1(hint);
  }
  let s = 4;
  if (net >= 35) s = 10;
  else if (net >= 22) s = 8.8;
  else if (net >= 14) s = 7.8;
  else if (net >= 8) s = 6.8;
  else if (net >= 3) s = 5.8;
  else if (net >= 0) s = 4.8;
  else if (net >= -8) s = 3.2;
  else s = 1.8;
  if (roi !== null && Number.isFinite(roi)) {
    if (roi >= 120) s = Math.min(10, s + 0.6);
    else if (roi >= 70) s = Math.min(10, s + 0.35);
    else if (roi < 0) s = Math.max(0, s - 0.8);
  }
  return round1(clamp(s, 0, 10));
}

function subscoreSupplyGap(d30: number, liveTotal: number): number {
  const supply = Math.max(1, liveTotal);
  const demand = d30 + 1;
  const ratio = demand / supply;
  // More solds per live listing → better gap
  let s = 3 + ratio * 9;
  if (d30 >= 6 && liveTotal <= 25) s += 1.2;
  return round1(clamp(s, 0, 10));
}

function subscoreBrandTier(brand: Record<string, unknown> | null): number {
  if (!brand) return 5;
  const tierRaw = String(brand.display_tier ?? brand.brand_tier ?? "").trim().toLowerCase();
  const n = parseInt(tierRaw.replace(/\D/g, ""), 10);
  if (tierRaw.includes("lux") || tierRaw.includes("premium") || tierRaw.includes("tier 1") || n === 1) {
    return 9;
  }
  if (tierRaw.includes("strong") || tierRaw.includes("high") || n === 2) return 7.6;
  if (tierRaw.includes("mid") || n === 3) return 6;
  if (tierRaw.includes("value") || tierRaw.includes("budget") || n === 4) return 4.5;
  if (tierRaw.length > 0) return 5.8;
  return 5;
}

function subscorePriceStability(median: number, iqr: number): number {
  if (median <= 0 || iqr < 0) return 5;
  const cv = iqr / median;
  // Lower spread → higher score
  const s = clamp(10 - cv * 12, 0, 10);
  return round1(s);
}

function seasonalModifier(month: number, blob: string): number {
  let m = 1;
  const winter = /coat|jacket|puffer|parka|hoodie|knit|sweater|fleece|gilet/i;
  const summer = /shorts|swim|tank|vest|sandals|slides|cap\b|bucket hat/i;
  if ((month === 11 || month === 12 || month === 1 || month === 2) && winter.test(blob)) m *= 1.025;
  if ((month >= 5 && month <= 8) && summer.test(blob)) m *= 1.02;
  if ((month >= 5 && month <= 8) && winter.test(blob)) m *= 0.98;
  if ((month === 11 || month === 12 || month === 1) && summer.test(blob)) m *= 0.98;
  return round1(clamp(m, 0.97, 1.03));
}

export function calculateFlipScore(input: CalculateFlipScoreInput): CalculateFlipScoreResult {
  const condRaw = String(input.condition_grade ?? "GOOD").toUpperCase();
  const condGrade = (CONDITION_MOD[condRaw] !== undefined ? condRaw : "GOOD") as FlipScoreConditionGrade;
  const conditionMod = CONDITION_MOD[condGrade] ?? 0.94;

  const { d7, d30, method } = resolveSoldVelocity(input.ebaySoldCards, input.soldMarkersOnPage);

  const vel = subscoreVelocity(d7, d30);
  const mar = subscoreMargin(input.buy_price_gbp, input.net_profit_gbp, input.roi_percent, input.resale_gbp);
  const supply = subscoreSupplyGap(d30, input.liveListingTotal);
  const brandS = subscoreBrandTier(input.brandRow);

  let med = input.ebayPriceMedian;
  let iqr = input.ebayPriceIqr;
  if ((med === undefined || med <= 0) || (iqr === undefined || iqr < 0)) {
    const iq = iqrFromPrices(input.ebayPrices);
    med = med && med > 0 ? med : iq.median;
    iqr = iqr !== undefined && iqr >= 0 ? iqr : iq.iqr;
  }
  const stab = subscorePriceStability(med ?? 0, iqr ?? 0);

  const weightedBase = round1(
    W_VELOCITY * vel +
      W_MARGIN * mar +
      W_SUPPLY * supply +
      W_BRAND * brandS +
      W_STAB * stab,
  );

  const month = input.month ?? new Date().getUTCMonth() + 1;
  const kw = (input.itemKeywords ?? []).join(" ").toLowerCase();
  const seasonal = seasonalModifier(month, kw);

  const afterCondition = weightedBase * conditionMod;
  const afterSeasonal = clamp(afterCondition * seasonal, 0, 10);
  const score = round1(afterSeasonal);

  const labels: Record<string, string> = {
    velocity: method === "days_ago" ? "Sold dates parsed from comps" : "Mixed dates — conservative proxy",
    margin: input.buy_price_gbp && input.buy_price_gbp > 0 ? "Uses your buy price + net" : "Enter buy price for full margin signal",
    supply_gap: "Sold pace vs live listings (eBay+Vinted+Depop)",
    brand_tier: input.brandRow ? "Brand tier from Marginn brands table" : "No brand row — baseline",
    price_stability: med > 0 ? "IQR vs median on sold £ prices" : "Limited price sample",
  };

  const breakdown: FlipScoreBreakdown = {
    velocity: vel,
    margin: mar,
    supply_gap: supply,
    brand_tier: brandS,
    price_stability: stab,
    weights: {
      velocity: W_VELOCITY,
      margin: W_MARGIN,
      supply_gap: W_SUPPLY,
      brand_tier: W_BRAND,
      price_stability: W_STAB,
    },
    weighted_base: weightedBase,
    condition_modifier: conditionMod,
    seasonal_modifier: seasonal,
    condition_grade: condGrade,
    sold_velocity: { d7, d30, method },
    labels,
  };

  return { score, breakdown };
}

/**
 * Marginn M-Score (0–100): weighted market + margin signals with tier-aware modifiers.
 *
 * weightedBase = Σ (weight_i × subscore_i)  [each subscore 0–10]
 * raw = weightedBase × conditionMult × seasonalMult × confidencePenalty
 * score = clamp(round(raw × 10), 0, 100)
 */

export type MScoreBrandTier = "HIGH" | "MED" | "LOW";
export type MScoreConditionGrade =
  | "LIKE_NEW"
  | "GOOD"
  | "LIGHT_WEAR"
  | "FADED"
  | "CRACKED_LOGO"
  | "STAINS"
  | "HEAVY_WEAR";

export interface CalculateMScoreInput {
  soldLast7: number;
  soldLast30: number;
  liveListings: number;
  avgPrice: number;
  minPrice: number;
  maxPrice: number;
  netProfit: number;
  brandTier: MScoreBrandTier;
  conditionGrade: string;
  itemType: string;
  brandConfidence: number;
  buyPrice: number;
  /** When < 5, sets lowConfidenceWarning. */
  listingCountUsed?: number;
  /** UTC month 1–12; defaults to now. */
  month?: number;
}

export interface MScoreBreakdown {
  velocityScore: number;
  marginScore: number;
  supplyGapScore: number;
  brandTierScore: number;
  stabilityScore: number;
}

export interface CalculateMScoreResult {
  score: number;
  verdict: "STRONG BUY" | "BUY" | "CAUTIOUS" | "SKIP";
  percentile: string;
  breakdown: MScoreBreakdown;
  multipliers: {
    condition: number;
    seasonal: number;
    confidence: number;
  };
  lowConfidenceWarning: boolean;
  signals: {
    velocityTrend: "accelerating" | "stable" | "slowing";
    supplyStatus: "undersupplied" | "balanced" | "oversupplied";
    marginHealth: "strong" | "moderate" | "weak";
  };
}

const WEIGHTS: Record<MScoreBrandTier, Record<string, number>> = {
  HIGH: { velocity: 0.2, margin: 0.2, supplyGap: 0.15, brandTier: 0.3, stability: 0.15 },
  MED: { velocity: 0.3, margin: 0.25, supplyGap: 0.2, brandTier: 0.15, stability: 0.1 },
  LOW: { velocity: 0.25, margin: 0.4, supplyGap: 0.15, brandTier: 0.1, stability: 0.1 },
};

const CONDITION_BY_TIER: Record<MScoreBrandTier, Record<string, number>> = {
  HIGH: {
    LIKE_NEW: 1.0,
    GOOD: 0.95,
    LIGHT_WEAR: 0.88,
    FADED: 0.7,
    CRACKED_LOGO: 0.55,
    STAINS: 0.4,
    HEAVY_WEAR: 0.35,
  },
  MED: {
    LIKE_NEW: 1.0,
    GOOD: 0.9,
    LIGHT_WEAR: 0.75,
    FADED: 0.55,
    CRACKED_LOGO: 0.4,
    STAINS: 0.25,
    HEAVY_WEAR: 0.2,
  },
  LOW: {
    LIKE_NEW: 1.0,
    GOOD: 0.8,
    LIGHT_WEAR: 0.55,
    FADED: 0.3,
    CRACKED_LOGO: 0.15,
    STAINS: 0.05,
    HEAVY_WEAR: 0.05,
  },
};

const COAT_JACKET_MONTH: Record<number, number> = {
  1: 0.7,
  2: 0.6,
  3: 0.5,
  4: 0.4,
  5: 0.3,
  6: 0.3,
  7: 0.4,
  8: 0.6,
  9: 0.9,
  10: 1.0,
  11: 1.0,
  12: 0.9,
};

const HOODIE_MONTH: Record<number, number> = {
  1: 0.9,
  2: 0.8,
  3: 0.7,
  4: 0.6,
  5: 0.5,
  6: 0.5,
  7: 0.6,
  8: 0.8,
  9: 1.0,
  10: 1.0,
  11: 0.9,
  12: 0.9,
};

const TEE_MONTH: Record<number, number> = {
  1: 0.6,
  2: 0.6,
  3: 0.7,
  4: 0.8,
  5: 1.0,
  6: 1.0,
  7: 1.0,
  8: 0.9,
  9: 0.7,
  10: 0.6,
  11: 0.5,
  12: 0.5,
};

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

function normalizeTier(raw: string): MScoreBrandTier {
  const u = raw.trim().toUpperCase();
  if (u === "HIGH") return "HIGH";
  if (u === "LOW") return "LOW";
  return "MED";
}

function normalizeCondition(raw: string): MScoreConditionGrade {
  const u = raw.trim().toUpperCase().replace(/\s+/g, "_");
  const allowed: MScoreConditionGrade[] = [
    "LIKE_NEW",
    "GOOD",
    "LIGHT_WEAR",
    "FADED",
    "CRACKED_LOGO",
    "STAINS",
    "HEAVY_WEAR",
  ];
  return (allowed.includes(u as MScoreConditionGrade) ? u : "GOOD") as MScoreConditionGrade;
}

function seasonalMultiplier(itemType: string, month: number): number {
  const t = itemType.toLowerCase();
  const m = clamp(month, 1, 12);
  if (/\b(coat|jacket|parka|puffer|gilet)\b/.test(t)) return COAT_JACKET_MONTH[m] ?? 0.9;
  if (/\b(hoodie|sweatshirt|crewneck|pullover)\b/.test(t)) return HOODIE_MONTH[m] ?? 0.9;
  if (/\b(t-?shirt|tee|tank)\b/.test(t)) return TEE_MONTH[m] ?? 0.9;
  if (/\b(trainer|sneaker|shoe|footwear)\b/.test(t)) return 1.0;
  return 0.9;
}

function velocityScore(soldLast7: number, soldLast30: number): { score: number; trend: number } {
  const recent = soldLast7 / 7;
  const olderDenom = Math.max(0, soldLast30 - soldLast7);
  const older = olderDenom / 23;
  const trend = older > 0.01 ? recent / older : recent > 0 ? 2 : 1;
  const score = Math.min(
    10,
    (soldLast30 / 20) * 10 * 0.7 + Math.min(trend, 2) * 0.3,
  );
  return { score: Math.max(0, score), trend };
}

function marginScore(netProfit: number): number {
  if (netProfit <= 0) return 0;
  return Math.min(10, Math.pow(netProfit / 10, 0.7) * 3.5);
}

function supplyGapScore(soldLast30: number, liveListings: number): { score: number; ratio: number } {
  const ratio = soldLast30 / Math.max(1, liveListings);
  return { score: Math.min(10, ratio * 3.5), ratio };
}

function brandTierScore(tier: MScoreBrandTier): number {
  if (tier === "HIGH") return 9.5;
  if (tier === "LOW") return 2.5;
  return 6.0;
}

function stabilityScore(avgPrice: number, minPrice: number, maxPrice: number): number {
  if (avgPrice <= 0) return 5;
  const cv = (maxPrice - minPrice) / avgPrice;
  return Math.max(0, 10 - cv * 8);
}

function confidencePenalty(confidence: number): number {
  if (confidence < 0.5) return 0.7;
  if (confidence < 0.7) return 0.88;
  return 1.0;
}

function verdictFromScore(score: number): CalculateMScoreResult["verdict"] {
  if (score > 75) return "STRONG BUY";
  if (score > 60) return "BUY";
  if (score > 40) return "CAUTIOUS";
  return "SKIP";
}

function percentileLabel(score: number): string {
  const top = clamp(100 - score, 1, 99);
  return `Top ${top}% of scans`;
}

export function calculateMScore(input: CalculateMScoreInput): CalculateMScoreResult {
  const tier = normalizeTier(input.brandTier);
  const cond = normalizeCondition(input.conditionGrade);
  const weights = WEIGHTS[tier];
  const month = input.month ?? new Date().getUTCMonth() + 1;

  const { score: velocityS, trend } = velocityScore(input.soldLast7, input.soldLast30);
  const marginS = marginScore(input.netProfit);
  const { score: supplyS, ratio: supplyRatio } = supplyGapScore(input.soldLast30, input.liveListings);
  const brandS = brandTierScore(tier);
  const stabilityS = stabilityScore(input.avgPrice, input.minPrice, input.maxPrice);

  const weightedBase =
    velocityS * weights.velocity +
    marginS * weights.margin +
    supplyS * weights.supplyGap +
    brandS * weights.brandTier +
    stabilityS * weights.stability;

  const conditionMult = CONDITION_BY_TIER[tier][cond] ?? CONDITION_BY_TIER.MED.GOOD;
  const seasonalMult = seasonalMultiplier(input.itemType, month);
  const confMult = confidencePenalty(input.brandConfidence);

  const raw = weightedBase * conditionMult * seasonalMult * confMult;
  const score = clamp(Math.round(raw * 10), 0, 100);

  const listingCount = input.listingCountUsed ?? input.soldLast30;
  const lowConfidenceWarning = listingCount < 5;

  let velocityTrend: CalculateMScoreResult["signals"]["velocityTrend"] = "stable";
  if (trend > 1.15) velocityTrend = "accelerating";
  else if (trend < 0.85) velocityTrend = "slowing";

  let supplyStatus: CalculateMScoreResult["signals"]["supplyStatus"] = "balanced";
  if (supplyRatio >= 2.5) supplyStatus = "undersupplied";
  else if (supplyRatio < 0.6) supplyStatus = "oversupplied";

  let marginHealth: CalculateMScoreResult["signals"]["marginHealth"] = "moderate";
  if (marginS >= 7) marginHealth = "strong";
  else if (marginS < 4) marginHealth = "weak";

  return {
    score,
    verdict: verdictFromScore(score),
    percentile: percentileLabel(score),
    breakdown: {
      velocityScore: Math.round(velocityS * 10) / 10,
      marginScore: Math.round(marginS * 10) / 10,
      supplyGapScore: Math.round(supplyS * 10) / 10,
      brandTierScore: Math.round(brandS * 10) / 10,
      stabilityScore: Math.round(stabilityS * 10) / 10,
    },
    multipliers: {
      condition: conditionMult,
      seasonal: seasonalMult,
      confidence: confMult,
    },
    lowConfidenceWarning,
    signals: {
      velocityTrend,
      supplyStatus,
      marginHealth,
    },
  };
}

/** Map brands row / item bucket to M-Score tier. */
export function mScoreTierFromBrandRow(brandRow: Record<string, unknown> | null, itemBucket: string): MScoreBrandTier {
  if (brandRow) {
    const dt = String(brandRow.display_tier ?? brandRow.brand_tier ?? "").trim().toUpperCase();
    if (dt === "HIGH" || dt === "LOW" || dt === "MED") return dt as MScoreBrandTier;
    const tier = String(brandRow.brand_tier ?? "").trim().toUpperCase();
    if (tier === "HIGH" || tier === "LOW" || tier === "MED") return tier as MScoreBrandTier;
  }
  const b = itemBucket.trim().toUpperCase();
  if (b === "HIGH" || b === "LOW") return b as MScoreBrandTier;
  return "MED";
}

/** Minimum live eBay sold comps before showing a resale £ figure in the app. */
export const MIN_EBAY_SOLD_COMPS_FOR_DISPLAY = 10;

export function ebayLiveCompCount(pricesLen: number, listingCardsLen: number): number {
  return Math.max(pricesLen, listingCardsLen);
}

export function shouldSuppressResaleDisplay(ebayLiveCompCount: number): boolean {
  return ebayLiveCompCount < MIN_EBAY_SOLD_COMPS_FOR_DISPLAY;
}

