/** Prefer outlier-filtered prices; if filtering removes everything, keep valid raw prices. */
export function deriveMarketPrices(rawPrices: number[]): number[] {
  const valid = rawPrices.filter((p) => Number.isFinite(p) && p > 0.5 && p < 5000);
  if (valid.length === 0) return [];
  const filtered = filterOutliers(valid);
  return filtered.length > 0 ? filtered : valid;
}

export function filterOutliers(prices: number[]): number[] {
  if (prices.length === 0) return [];
  const floored = prices.filter((p) => p >= 2);
  if (floored.length === 0) return [];
  if (floored.length === 1) return floored;
  const rawAvg = floored.reduce((a, b) => a + b, 0) / floored.length;
  const firstPass = floored.filter((p) => p >= rawAvg * 0.2 && p <= rawAvg * 3);
  if (firstPass.length === 0) return floored;
  const cleanAvg = firstPass.reduce((a, b) => a + b, 0) / firstPass.length;
  const secondPass = firstPass.filter((p) => p >= cleanAvg * 0.25 && p <= cleanAvg * 2.5);
  return secondPass.length > 0 ? secondPass : firstPass;
}

function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

function logScrapingBeeAuthFailure(context: string, status: number, body: string): void {
  const diag = scrapingBeeKeyDiag();
  console.warn(
    `[marketVision] ScrapingBee ${context} auth/status ${status}`,
    JSON.stringify({
      key_source: scrapingBeeKeySource(),
      key_prefix8: diag.prefix8,
      key_len: diag.length,
      body_snip: body.slice(0, 200),
    }),
  );
}

/** ScrapingBee HTML fetch — shared by market vision and whitelist builders. */
export async function scrapePageHtml(targetUrl: string): Promise<string> {
  const key = scrapingBeeKey();
  if (!key) {
    console.warn("[marketVision] SCRAPINGBEE_API_KEY missing — skip HTML scrape");
    return "";
  }
  const params = new URLSearchParams({
    api_key: key,
    url: targetUrl,
    render_js: "false",
    premium_proxy: "false",
    block_ads: "true",
    timeout: String(SCRAPE_TIMEOUT_MS),
  });
  const res = await fetch(`https://app.scrapingbee.com/api/v1/?${params.toString()}`, {
    signal: AbortSignal.timeout(SCRAPE_TIMEOUT_MS + 3_000),
  });
  if (!res.ok) {
    const errText = await res.text();
    if (res.status === 401) logScrapingBeeAuthFailure("html", res.status, errText);
    else console.warn("[marketVision] HTML scrape failed", res.status, errText.slice(0, 120));
    return "";
  }
  return await res.text();
}

async function scrapeScreenshot(
  targetUrl: string,
  screenshotSelector: string | undefined,
): Promise<string | null> {
  const key = scrapingBeeKey();
  if (!key) {
    console.warn("[marketVision] SCRAPINGBEE_API_KEY missing — skip screenshot");
    return null;
  }
  const params = new URLSearchParams({
    api_key: key,
    url: targetUrl,
    render_js: "false",
    premium_proxy: "false",
    screenshot: "true",
    screenshot_full_page: "false",
    timeout: String(SCRAPE_TIMEOUT_MS),
  });
  if (screenshotSelector?.trim()) {
    params.set("screenshot_selector", screenshotSelector.trim());
  }
  const res = await fetch(`https://app.scrapingbee.com/api/v1/?${params.toString()}`, {
    signal: AbortSignal.timeout(SCRAPE_TIMEOUT_MS + 5_000),
  });
  if (!res.ok) {
    const errText = await res.text();
    if (res.status === 401) {
      logScrapingBeeAuthFailure(`screenshot:${screenshotSelector ?? "viewport"}`, res.status, errText);
    } else {
      console.warn(
        "[marketVision] screenshot failed",
        res.status,
        screenshotSelector ?? "viewport",
        errText.slice(0, 120),
      );
    }
    return null;
  }
  const ct = (res.headers.get("content-type") ?? "").toLowerCase();
  if (!ct.includes("image") && !ct.includes("octet-stream")) {
    const text = await res.text();
    console.warn("[marketVision] screenshot not image, len", text.length);
    return null;
  }
  return arrayBufferToBase64(await res.arrayBuffer());
}

function visionPromptForPlatform(platform: "vinted" | "depop"): string {
  const site =
    platform === "vinted"
      ? "Vinted UK catalog search results"
      : "Depop UK search results (used items)";
  return `You are a precise data extraction AI. This is a screenshot of ${site}. Extract every visible listing and return ONLY this JSON with no other text:
{
  "listings": [
    {
      "title": "exact item title",
      "price": 0,
      "condition": "condition grade if visible or empty string",
      "days_ago": null,
      "image_url": ""
    }
  ]
}
Rules:
- price must be the item sold/listing price in GBP as a number only (no £ symbol). Ignore shipping-only lines.
- days_ago: integer days since sold if shown, else null.
- Only include rows with a clear GBP item price. Ignore promoted/sponsored slots without a real price.
- If no listings are visible, return "listings": [].`;
}

async function extractListingsFromScreenshot(
  screenshotBase64: string,
  platform: "vinted" | "depop",
): Promise<MarketListing[]> {
  const key = anthropicKeyOptional();
  if (!key) {
    console.warn("[marketVision] ANTHROPIC_API_KEY missing — skip vision extraction");
    return [];
  }

  const res = await fetch(ANTHROPIC_API_URL, {
    method: "POST",
    headers: {
      "x-api-key": key,
      "anthropic-version": "2023-06-01",
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: VISION_MODEL,
      max_tokens: 2048,
      messages: [
        {
          role: "user",
          content: [
            {
              type: "image",
              source: { type: "base64", media_type: "image/png", data: screenshotBase64 },
            },
            { type: "text", text: visionPromptForPlatform(platform) },
          ],
        },
      ],
    }),
    signal: AbortSignal.timeout(45_000),
  });

  if (!res.ok) {
    console.warn("[marketVision] Claude vision failed", platform, res.status);
    return [];
  }

  const data = await res.json();
  const rawText = data?.content?.[0]?.text ?? "";
  return parseVisionListingsJson(rawText);
}

function parseVisionListingsJson(rawText: string): MarketListing[] {
  try {
    let cleaned = rawText.replace(/```json\s*/gi, "").replace(/```\s*/g, "").trim();
    const first = cleaned.indexOf("{");
    const last = cleaned.lastIndexOf("}");
    if (first !== -1 && last > first) cleaned = cleaned.slice(first, last + 1);
    const parsed = JSON.parse(cleaned) as { listings?: unknown[] };
    if (!Array.isArray(parsed.listings)) return [];
    const out: MarketListing[] = [];
    for (const row of parsed.listings) {
      if (!row || typeof row !== "object") continue;
      const o = row as Record<string, unknown>;
      const title = String(o.title ?? "").trim();
      const price = Number(o.price);
      if (!title || !Number.isFinite(price) || price <= 0 || price > 5000) continue;
      const daysRaw = o.days_ago;
      let days_ago: number | null = null;
      if (typeof daysRaw === "number" && Number.isFinite(daysRaw) && daysRaw >= 0 && daysRaw < 400) {
        days_ago = Math.round(daysRaw);
      }
      out.push({
        title,
        price: Math.round(price * 100) / 100,
        image_url: String(o.image_url ?? "").trim(),
        listing_url: "",
        days_ago,
        condition: String(o.condition ?? "").trim() || undefined,
        relevance_score: 0,
      });
    }
    return out;
  } catch (e) {
    console.warn("[marketVision] parse vision JSON failed", e instanceof Error ? e.message : "unknown");
    return [];
  }
}

export function relevanceScoreForTitle(
  title: string,
  brandName: string,
  itemType: string,
): number {
  const t = title.toLowerCase();
  let score = 0;
  const brandTokens = brandName.toLowerCase().split(/[\s/]+/).filter((w) => w.length > 2);
  for (const w of brandTokens) {
    if (t.includes(w)) score += 0.28;
  }
  const item = itemType.trim().toLowerCase();
  if (item && item !== "unknown" && t.includes(item)) score += 0.32;
  if (/\b(nike|adidas|stone island|supreme|ralph|carhartt)\b/i.test(t) && brandTokens.some((w) => t.includes(w))) {
    score += 0.1;
  }
  return Math.min(1, Math.round(score * 1000) / 1000);
}

function applyRelevance(listings: MarketListing[], brandName: string, itemType: string): MarketListing[] {
  return listings.map((l) => ({
    ...l,
    relevance_score: relevanceScoreForTitle(l.title, brandName, itemType),
  }));
}

function regexVinted(html: string): number[] {
  const rawPrices: number[] = [];
  const priceRegex = /£\s*(\d+(?:\.\d{1,2})?)/g;
  let m: RegExpExecArray | null;
  while ((m = priceRegex.exec(html)) !== null) {
    const v = parseFloat(m[1]);
    if (v > 0.5 && v < 5000) rawPrices.push(v);
  }
  return deriveMarketPrices(rawPrices);
}

function regexDepop(html: string): number[] {
  return regexVinted(html);
}

const PLATFORM_SCREENSHOT_SELECTORS: Record<
  "vinted" | "depop",
  string[]
> = {
  vinted: [".feed-grid"],
  depop: [".sc-eDnWTT", "[data-testid='product-grid']", ".styles_productGrid__"],
};

function keywordsFromEbaySearchUrl(searchUrl: string): string {
  try {
    const u = new URL(searchUrl);
    return decodeURIComponent(u.searchParams.get("_nkw") ?? "").trim();
  } catch {
    return "";
  }
}

/**
 * eBay: Finding API `findCompletedItems`. Vinted/Depop: ScrapingBee vision + HTML fallback.
 */
export async function extractPlatformMarketData(args: {
  platform: "ebay" | "vinted" | "depop";
  searchUrl: string;
  brandName: string;
  itemType: string;
  /** eBay Finding API keywords (preferred over parsing `searchUrl`). */
  searchKeywords?: string;
}): Promise<PlatformMarketResult> {
  const { platform, searchUrl, brandName, itemType } = args;

  if (platform === "ebay") {
    const keywords = (args.searchKeywords ?? keywordsFromEbaySearchUrl(searchUrl)).trim();
    const { fetchEbaySoldViaFindingApi } = await import("./ebayFindingApi.ts");
    return await fetchEbaySoldViaFindingApi({
      keywords,
      brandName,
      itemType,
    });
  }

  const selectors = PLATFORM_SCREENSHOT_SELECTORS[platform];

  let screenshotB64: string | null = null;
  for (const sel of selectors) {
    screenshotB64 = await scrapeScreenshot(searchUrl, sel);
    if (screenshotB64) break;
  }
  if (!screenshotB64) {
    screenshotB64 = await scrapeScreenshot(searchUrl, undefined);
  }

  if (screenshotB64) {
    let listings = applyRelevance(
      await extractListingsFromScreenshot(screenshotB64, platform),
      brandName,
      itemType,
    );
    if (listings.length > 0) {
      const prices = deriveMarketPrices(listings.map((l) => l.price));
      const soldCount = listings.filter((l) => l.days_ago !== null && l.days_ago <= 30).length;
      return {
        platform,
        prices,
        listings: listings.slice(0, 12),
        method: "vision",
        soldCount: soldCount || listings.length,
      };
    }
    console.log(`[marketVision] ${platform}: vision returned 0 listings, regex fallback`);
  } else {
    console.log(`[marketVision] ${platform}: screenshot failed, regex fallback`);
  }

  const html = await scrapePageHtml(searchUrl);
  const prices =
    platform === "vinted" ? regexVinted(html) : regexDepop(html);
  return {
    platform,
    prices,
    listings: [],
    method: "regex_fallback",
    soldCount: 0,
  };
}

/**
 * AI Comparable Finder — text-only scoring across eBay / Vinted / Depop listings.
 */
import type { MarketListing } from "./marketVisionScrape.ts";

export type ComparablePlatform = "ebay" | "vinted" | "depop";

export interface ItemDetails {
  brand: string;
  type: string;
  colour: string;
  condition: string;
  size: string;
}

export interface ComparableListing {
  id: string;
  platform: ComparablePlatform;
  title: string;
  price: number;
  /** ISO date when sold/listed if known */
  date_at: string | null;
  days_ago: number | null;
  match_percent: number;
  url: string;
}

export interface PlatformComparablesSlice {
  top5: ComparableListing[];
  strong_match_count: number;
  low_confidence: boolean;
}

export interface FindBestComparablesResult {
  ebay: PlatformComparablesSlice;
  vinted: PlatformComparablesSlice;
  depop: PlatformComparablesSlice;
  all_passing: ComparableListing[];
  average_price: number | null;
  overall_confidence: number;
  /** Context for client M-Score recalc after user removals */
  m_score_recalc?: {
    sold_last7: number;
    sold_last30: number;
    live_listings: number;
    net_profit: number;
    brand_tier: string;
    condition_grade: string;
    item_type: string;
    brand_confidence: number;
    buy_price: number;
    month: number;
  };
}

export interface FindBestComparablesDiscard {
  item_brand: string;
  item_type: string;
  discarded_listing_title: string;
  discarded_price: number | null;
  match_score: number;
  platform: ComparablePlatform;
}

const MIN_MATCH = 0.7;
const STRONG_MATCH = 0.8;
const MIN_STRONG_FOR_AVG = 3;
const RECENCY_WINDOW_DAYS = 90;

const BRAND_ALIASES: Record<string, string[]> = {
  "carhartt wip": ["carhartt", "wip"],
  "ralph lauren": ["polo", "rl"],
  "stone island": ["stoney", "si"],
  "north face": ["tnf", "the north face"],
};

const CONDITION_TERMS: Record<string, string[]> = {
  LIKE_NEW: ["like new", "bnwt", "brand new", "new with tags", "unworn", "mint", "nwt"],
  GOOD: ["good", "excellent", "vgc", "very good", "great condition"],
  LIGHT_WEAR: ["light wear", "worn once", "lightly worn", "minor wear"],
  FADED: ["faded", "fade", "sun faded"],
  CRACKED_LOGO: ["cracked logo", "logo crack", "peeling logo"],
  STAINS: ["stain", "stained", "mark", "spot"],
  HEAVY_WEAR: ["heavy wear", "well worn", "distressed", "beat up", "damaged", "hole", "rip"],
};

const TYPE_SYNONYMS: Record<string, string[]> = {
  hoodie: ["hoodie", "hoody", "pullover", "sweatshirt"],
  jacket: ["jacket", "coat", "parka", "bomber", "windbreaker", "gilet"],
  trainers: ["trainer", "sneaker", "shoe", "footwear"],
  tshirt: ["t-shirt", "tee", "t shirt"],
  jeans: ["jean", "denim", "trouser", "pant"],
  shirt: ["shirt", "oxford", "button down", "polo"],
};

const COLOUR_GROUPS: Record<string, string[]> = {
  black: ["black", "blk", "noir"],
  white: ["white", "cream", "off white", "ivory"],
  navy: ["navy", "dark blue"],
  blue: ["blue", "cobalt", "royal"],
  grey: ["grey", "gray", "charcoal", "heather"],
  green: ["green", "olive", "khaki", "sage"],
  red: ["red", "burgundy", "maroon", "wine"],
  brown: ["brown", "tan", "beige", "camel"],
  pink: ["pink", "rose"],
  yellow: ["yellow", "mustard"],
  orange: ["orange", "rust"],
  purple: ["purple", "lilac", "violet"],
};

function norm(s: string): string {
  return s
    .toLowerCase()
    .replace(/['']/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function tokens(s: string): string[] {
  return norm(s).split(" ").filter((w) => w.length > 1);
}

function stableId(platform: ComparablePlatform, title: string, price: number, url: string): string {
  const key = `${platform}|${norm(title)}|${price}|${url}`;
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return `${platform}-${(h >>> 0).toString(16)}`;
}

function brandScore(title: string, brand: string): number {
  const t = norm(title);
  const b = norm(brand);
  if (!b || b === "unknown") return 0.45;
  if (t.includes(b)) return 1;
  const brandToks = tokens(b);
  let hits = 0;
  for (const tok of brandToks) {
    if (tok.length > 2 && t.includes(tok)) hits += 1;
  }
  if (brandToks.length > 0 && hits >= Math.min(brandToks.length, 2)) return 0.92;
  if (hits > 0) return 0.75 + 0.08 * hits;
  const aliases = BRAND_ALIASES[b];
  if (aliases?.some((a) => t.includes(a))) return 0.88;
  for (const [canonical, als] of Object.entries(BRAND_ALIASES)) {
    if (b.includes(canonical) || canonical.includes(b)) {
      if (als.some((a) => t.includes(a))) return 0.85;
    }
  }
  return hits > 0 ? 0.7 : 0.2;
}

function typeScore(title: string, itemType: string): number {
  const t = norm(title);
  const it = norm(itemType);
  if (!it || it === "unknown") return 0.5;
  if (t.includes(it)) return 1;
  for (const [key, syns] of Object.entries(TYPE_SYNONYMS)) {
    if (it.includes(key) || key.includes(it)) {
      if (syns.some((s) => t.includes(s))) return 0.95;
    }
  }
  const typeToks = tokens(itemType);
  let hits = 0;
  for (const tok of typeToks) {
    if (tok.length > 3 && t.includes(tok)) hits += 1;
  }
  if (hits >= 2) return 0.9;
  if (hits === 1) return 0.72;
  return 0.35;
}

function conditionScore(title: string, listingCondition: string | undefined, target: string): number {
  const t = `${norm(title)} ${norm(listingCondition ?? "")}`;
  const grade = target.toUpperCase().replace(/\s+/g, "_");
  const terms = CONDITION_TERMS[grade] ?? CONDITION_TERMS.GOOD ?? [];
  if (terms.some((term) => t.includes(term))) return 1;
  const order = [
    "LIKE_NEW",
    "GOOD",
    "LIGHT_WEAR",
    "FADED",
    "CRACKED_LOGO",
    "STAINS",
    "HEAVY_WEAR",
  ];
  const idx = order.indexOf(grade as (typeof order)[number]);
  if (idx === -1) return 0.55;
  for (let d = 1; d <= 2; d++) {
    const near = order[idx - d] ?? order[idx + d];
    if (!near) continue;
    const nearTerms = CONDITION_TERMS[near] ?? [];
    if (nearTerms.some((term) => t.includes(term))) return 0.78 - d * 0.08;
  }
  return 0.45;
}

function colourScore(title: string, colour: string): number {
  const c = norm(colour);
  if (!c || c === "unknown" || c === "multi") return 0.55;
  const t = norm(title);
  const colourToks = tokens(colour);
  for (const tok of colourToks) {
    if (tok.length > 2 && t.includes(tok)) return 1;
  }
  for (const [, group] of Object.entries(COLOUR_GROUPS)) {
    const inTarget = group.some((g) => c.includes(g) || colourToks.some((ct) => ct.includes(g)));
    const inTitle = group.some((g) => t.includes(g));
    if (inTarget && inTitle) return 0.92;
  }
  return 0.35;
}

function recencyScore(daysAgo: number | null): number {
  if (daysAgo === null || !Number.isFinite(daysAgo)) return 0.55;
  if (daysAgo <= 7) return 1;
  if (daysAgo <= RECENCY_WINDOW_DAYS) {
    return 1 - (daysAgo / RECENCY_WINDOW_DAYS) * 0.35;
  }
  return 0.25;
}

function sizeScore(title: string, size: string): number {
  const s = norm(size);
  if (!s || s === "unknown" || s === "one size") return 0.6;
  const t = norm(title);
  if (t.includes(s)) return 1;
  const m = s.match(/\b(xs|s|m|l|xl|xxl|xxxl|\d{2})\b/);
  if (m && t.includes(m[1])) return 0.9;
  return 0.5;
}

function scoreListing(
  listing: MarketListing,
  platform: ComparablePlatform,
  item: ItemDetails,
): { score: number; listing: ComparableListing } {
  const brandS = brandScore(listing.title, item.brand);
  const typeS = typeScore(listing.title, item.type);
  const condS = conditionScore(listing.title, listing.condition, item.condition);
  const colourS = colourScore(listing.title, item.colour);
  const recencyS = recencyScore(listing.days_ago);
  const sizeS = sizeScore(listing.title, item.size);

  const score =
    brandS * 0.28 +
    typeS * 0.24 +
    condS * 0.16 +
    colourS * 0.14 +
    recencyS * 0.12 +
    sizeS * 0.06;

  const rounded = Math.round(score * 1000) / 1000;
  const dateAt =
    listing.days_ago != null && Number.isFinite(listing.days_ago)
      ? new Date(Date.now() - listing.days_ago * 86_400_000).toISOString()
      : null;

  return {
    score: rounded,
    listing: {
      id: stableId(platform, listing.title, listing.price, listing.listing_url),
      platform,
      title: listing.title,
      price: listing.price,
      date_at: dateAt,
      days_ago: listing.days_ago,
      match_percent: Math.round(rounded * 100),
      url: listing.listing_url,
    },
  };
}

function median(nums: number[]): number {
  if (nums.length === 0) return 0;
  const sorted = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0
    ? sorted[mid]!
    : Math.round((sorted[mid - 1]! + sorted[mid]!) / 2);
}

function slicePlatform(
  scored: Array<{ score: number; listing: ComparableListing }>,
): PlatformComparablesSlice {
  const passing = scored
    .filter((s) => s.score >= MIN_MATCH)
    .sort((a, b) => b.score - a.score || a.listing.price - b.listing.price);
  const strong = passing.filter((s) => s.score >= STRONG_MATCH);
  const top5 = passing.slice(0, 5).map((s) => s.listing);
  return {
    top5,
    strong_match_count: strong.length,
    low_confidence: strong.length < MIN_STRONG_FOR_AVG,
  };
}

function computeAveragePrice(slices: PlatformComparablesSlice[]): number | null {
  const prices: number[] = [];
  for (const slice of slices) {
    if (slice.low_confidence) continue;
    for (const row of slice.top5) {
      if (Number.isFinite(row.price) && row.price > 0) prices.push(row.price);
    }
  }
  if (prices.length === 0) return null;
  return median(prices);
}

function overallConfidenceScore(
  slices: PlatformComparablesSlice[],
  allPassing: ComparableListing[],
): number {
  const strongTotal = slices.reduce((n, s) => n + s.strong_match_count, 0);
  const topMatches = allPassing
    .slice(0, 15)
    .map((l) => l.match_percent);
  const avgMatch =
    topMatches.length > 0
      ? topMatches.reduce((a, b) => a + b, 0) / topMatches.length
      : 0;
  const coverage = Math.min(1, strongTotal / 9);
  return Math.round(clamp(coverage * 35 + (avgMatch / 100) * 65, 0, 100));
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

function collectDiscards(
  item: ItemDetails,
  platform: ComparablePlatform,
  raw: MarketListing[],
  passingIds: Set<string>,
): FindBestComparablesDiscard[] {
  const out: FindBestComparablesDiscard[] = [];
  for (const row of raw) {
    const { score, listing } = scoreListing(row, platform, item);
    if (score >= MIN_MATCH || passingIds.has(listing.id)) continue;
    if (score < 0.45) continue;
    out.push({
      item_brand: item.brand,
      item_type: item.type,
      discarded_listing_title: row.title,
      discarded_price: Number.isFinite(row.price) ? row.price : null,
      match_score: score,
      platform,
    });
  }
  return out;
}

export function findBestComparables(
  itemDetails: ItemDetails,
  ebayResults: MarketListing[],
  vintedResults: MarketListing[],
  depopResults: MarketListing[],
): FindBestComparablesResult {
  const item: ItemDetails = {
    brand: String(itemDetails.brand ?? "").trim(),
    type: String(itemDetails.type ?? "").trim(),
    colour: String(itemDetails.colour ?? "").trim(),
    condition: String(itemDetails.condition ?? "GOOD").trim(),
    size: String(itemDetails.size ?? "").trim(),
  };

  const scorePlatform = (listings: MarketListing[], platform: ComparablePlatform) =>
    listings.map((l) => scoreListing(l, platform, item));

  const ebayScored = scorePlatform(ebayResults, "ebay");
  const vintedScored = scorePlatform(vintedResults, "vinted");
  const depopScored = scorePlatform(depopResults, "depop");

  const ebay = slicePlatform(ebayScored);
  const vinted = slicePlatform(vintedScored);
  const depop = slicePlatform(depopScored);

  const all_passing = [...ebayScored, ...vintedScored, ...depopScored]
    .filter((s) => s.score >= MIN_MATCH)
    .sort((a, b) => b.score - a.score)
    .map((s) => s.listing);

  const average_price = computeAveragePrice([ebay, vinted, depop]);
  const overall_confidence = overallConfidenceScore([ebay, vinted, depop], all_passing);

  return {
    ebay,
    vinted,
    depop,
    all_passing,
    average_price,
    overall_confidence,
  };
}

export function collectComparableDiscards(
  itemDetails: ItemDetails,
  ebayResults: MarketListing[],
  vintedResults: MarketListing[],
  depopResults: MarketListing[],
  result: FindBestComparablesResult,
): FindBestComparablesDiscard[] {
  const passingIds = new Set(result.all_passing.map((l) => l.id));
  return [
    ...collectDiscards(itemDetails, "ebay", ebayResults, passingIds),
    ...collectDiscards(itemDetails, "vinted", vintedResults, passingIds),
    ...collectDiscards(itemDetails, "depop", depopResults, passingIds),
  ].slice(0, 80);
}

/**
 * Centralised Edge Function secret reads (Deno.env only — never hard-code keys).
 * Logs once per isolate cold start so deploys can verify secrets loaded.
 */

export type EdgeSecretDiag = {
  present: boolean;
  /** Which env var supplied the value (if any). */
  source: string | null;
  /** First 8 characters for deploy verification — never log full keys. */
  prefix8: string;
  length: number;
};

function cleanSecret(raw: string | undefined): string {
  if (!raw) return "";
  let s = raw.trim();
  // Dashboard paste often wraps values in quotes.
  if (
    (s.startsWith('"') && s.endsWith('"')) ||
    (s.startsWith("'") && s.endsWith("'"))
  ) {
    s = s.slice(1, -1).trim();
  }
  return s;
}

function readFirstSecret(names: readonly string[]): { value: string; source: string | null } {
  for (const name of names) {
    const value = cleanSecret(Deno.env.get(name));
    if (value) return { value, source: name };
  }
  return { value: "", source: null };
}

function diag(names: readonly string[]): EdgeSecretDiag {
  const { value, source } = readFirstSecret(names);
  return {
    present: value.length > 0,
    source,
    prefix8: value.length > 0 ? value.slice(0, 8) : "",
    length: value.length,
  };
}

